-- GENERATED by `wfj generate` from data/quest/quest-0099.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [99046] = { "行方不明の伝令", "Oracle Gladeへ続く道で、Sentinel Eralya Leafshadowを探してください。", "Council of the Forestは少し前、少数の歩哨をOracle Treeへ送りました。その木は長老たちに言葉を送り、それを無事にDarnassusへ届けるのが私たちの務めです。\n\n最近の伝令がまだ到着していないと知らせを受けました。Oracleの言葉が届く頻度はまちまちですが、今回は異常に長く空いています。\n\n西への道を通ってOracle Gladeへ向かい、彼女の様子を見てきてください。Eralya Leafshadowの番だったはずで、彼女はまだ訓練中なのです。Eluneのお導きを。", nil, "Eluneの恵みよ……私は死なない……独りでは……", 0x0e4bd39c, 0x86645c27, 0xfc11cf97, nil, 0x17c4d4f1, "...m." },
  [99047] = { "まだ死んでいない", "Sentinel Eralya Leafshadowのため、DolanaarのByancieに助けを求めて下さい。", "姉妹たちと私は……遣わされて……Oracle Tree……\n\n木……伝言。私……ハーピーが……そこらじゅうに……\n\n<Eralyaは血を吐き、痛みに顔をゆがめる。>\n\n私はもう長くないかも……誰も来ない。どうか……Byancie……Dolanaarの……", nil, "harpiesも、森のあちこちに現れているのと同じ邪悪なものに侵されています。Sentinel Eralyaを苦しめているのも、きっとそれでしょう。\n\n急がなければ。彼女が傷に屈するまで、そう長くはありません。", 0x3a868dfa, 0x445fdebf, 0x584dfcb5, nil, 0xd9ac52e3, "...m." },
  [99048] = { "足りない人手", "Tiragarde Keepの北でHeglan Shadeeyeを見つけてください。", "Shattered Handの一員、もっと……巧妙な戦い方をする集団の者が、遠くからTiragarde Keepを見張っていた。その彼女からの報告が、突然途絶えた。\n\n人間どもに捕まったとは思えん。もっと危険な何かが絡んでいるんじゃないかと心配だ。彼女を見つけられるか探ってくれ。伝言が遅れているだけならいいんだが。", nil, "Heglanの亡骸が、小屋の残骸の中で冷たく横たわっている。\n\n彼女を殺したものは人間ではないようだ。近くに何が起きたかの痕跡があるかもしれない。", 0xa4d92e86, 0x200e76ca, 0xf2e0d401, nil, 0x5727259c, "...m." },
  [99049] = { "下からの脅威", "Heglan Shadeeyeを襲ったものの痕跡を見つけてください。", "近くの一帯は荒らされ、明らかに小競り合いの跡がある。Heglanを襲ったものも、無傷では済まなかったようだ。近くに何が起きたのかを示す痕跡がありそうだ。\n\nOrgnilは、襲撃者が残した証拠を見たがるだろう。", "彼女は見つかったか？", "この旗と刃の欠片はnagaのものだ！北から海岸沿いに下ってきたに違いない。\n\nここで奴らに足場を築かせるわけにはいかん。両方向からの圧力は、Razor Hillには耐えきれんだろう。", 0x2f83a976, 0x9675fa5a, 0xd4910657, 0x59d9237b, 0xa5f143e0, "....." },
  [99050] = { "大樹の恵み", "DolanaarにいるByancieのために、Dewy Lasher Frondを$N1個と、Empty VialとRefreshing Spring Waterをそれぞれ一つ集めてください。", "Eralyaがここに戻ってさらに治療を受けられるまで、病を食い止めておくのに必要な材料を集めるのを手伝ってください。\n\nありがたいことに、私たちの生きた故郷は今も豊かで、困った時には恵みを与えてくれます。\n\n主な材料はdewy lasherの葉です。ここから真南のLake Al'Ameth周辺か、北西のWellspring Lakeとその川で見つかるでしょう。\n\nそれに加えて、empty vialとspring waterが必要です。どちらもこの町で買えますし、交換で手に入れることもできます。", "材料はそろったか？Eralyaはもう長くないのではと心配だ。", "助けてくれてありがとう。どうか、小瓶と水の費用の足しにこれを受け取ってください。\n\nさて、軟膏を作りましょう。すぐに済むはずです。", 0xa032b794, 0x349f6651, 0x1904360b, 0x5b2d6269, 0xe1b52a22, "....." },
  [99051] = { "下からの脅威", "Naga Spinefinを$N1個集めてください。", "あの蛇どもが我らを煩わせたのは、これが初めてではない。奴らがここでは歓迎されないことを思い知らせてやらねばならん。\n\n奴らの斥候が野営地を築いている場所を探し出し、皆殺しにしろ。証として奴らのひれを持ち帰れ。奴らにわからせるため、素早く動く必要がある。", "あの蛇のクズどもに困らされてはいないだろうな？", "これで奴らが北へ逃げ帰ってくれるといいが。兵卒を何人か置いて、はぐれ者や妙な真似をする奴がいないか見張らせておこう。", 0x2f83a976, 0x543e1c8e, 0x1edfcef1, 0x14500e82, 0xdc75c01b, "....." },
  [99052] = { "下からの脅威", "Durotarの北の海岸にいる海の巨人を倒し、倒した証を持ち帰ってください。", "斥候のひとりから、あのnagaを追ってsea giantがここまで降りてきたと報告があった。nagaがわざと連れてきたのかどうかはわからんが、いずれにせよ危険な奴だ。\n\n若い個体だが、不意を突かれれば、それでもオークを一瞬で真っ二つに引き裂けるだろう。そいつを消してほしい。だが、始末するには助けを見つけた方がいいぞ。", "奴らに血と雷を見舞ってやれ！", "ハッ！ここまで奴の体が倒れる音が聞こえたぞ！\n\n今日の獲物を誇りに思え。海の巨人との戦いを生き延びたと言える者は多くない。", 0x2f83a976, 0xc84640a7, 0xedda7a5d, 0x72b63775, 0x70afadf2, "....." },
  [99053] = { "Ban'ethilからの脱出", "Sentinel Lynessa DuskblossomがBan'ethil Barrow Denから脱出するのを手伝い、彼女の無事をDolanaarのSentinel Kyra Starsongに報告して下さい。", "祈りが届きました！ ここまで戦いながら降りてきてくださったことに感謝します。\n\n私はOracle Treeから、ここで眠るドルイドたちに伝言を届けるよう遣わされたのですが、来てみるとfurbolgにすっかり占拠されていたのです！ 引き返す前に待ち伏せされて、ここまで連れてこられました……次の食事にされるのではと恐れています。\n\nあなたはどうか知りませんが、私はこの場所が大嫌いです。地の下はkaldoreiのいる場所ではありません。", nil, "あなたがいてくれたおかげで、LynessaがGnarlpineの手で暗い運命をたどらずに済みました。Eluneに感謝を。彼女は私たちの中でも指折りの者で、私の個人的な友でもあります。\n\nどうか、お礼にこれを受け取ってください。kaldoreiを守る助けとなりますように。", 0xd6762ffb, 0xcbcfdcbe, 0x6fd4ed25, nil, 0x6891dce3, "...m." },
  [99073] = { "苦痛を和らげる", "Lashwater SalveをOracle Treeへ向かう道にいるSentinel Eralya Leafshadowに届けてください。", "軟膏ができました。急いでEralyaのもとへ持っていってください。\n\n本当に彼女を治せるかはわかりません。腐敗は急速に膿み、広がるにつれて力を増していきます。\n\n少なくとも、彼女の苦しみは和らぐでしょう。それだけでも急ぐ価値はあります。", "<Eralyaはもう言葉で応えなくなった。弱々しく喉を鳴らすような吐息だけが、まだ生きていることを示している。>", "<軟膏を飲み込む手助けをすると、Eralyaの呼吸はすぐに落ち着いた。助からないかもしれないが、ひとまずは安らいでいる。>", 0xda4d0dec, 0x646356c4, 0x9303e52b, 0x0654ca00, 0x45eb9e05, "....." },
  [99079] = { "Longwalker Malah", "Bloodhoof Villageの東、Mulgoreの端の近くでLongwalker Malah Longwindを見つけてください。", "Longwalkersは、我らの民で最も信頼の厚い斥候だ。彼らの忠誠はHigh Chieftainただひとりに捧げられているが、若きBaineも時に彼らの助けを求める。\n\n今がまさにその時だ。Longwalker Malahが東の境界付近へ遣わされたのだが、3日が経った昨夜になっても戻らなかった。こういう時は、彼らの無事を確かめるのが我らの務めだ。\n\n私は村の安全を守らねばならん。力を示し、Malahを探し出してくれ。Longwalkersの象徴である鉢巻きと羽根飾りの杖で、彼女だとわかるはずだ。", nil, "Malahが自然に死んだのではないことは明らかだ。彼女の背中と付近の地面には矢が突き刺さっている。", 0x0e88eaca, 0x14849b43, 0xa8750e80, nil, 0x3df404da, "...m." },
  [99080] = { "奴らを追い払う", "Galak Centaurを$N1体、Galak Outrunnerを$N2体倒し、Herak the Pillagerの首をBaine Bloodhoofのところへ持って行ってください。", "我が言葉をよく聞け。centaurには草の一本たりとも渡しはせぬ。\n\n奴らが休息を取り、我らの村へ攻め寄せる機会を得る前に、今すぐ奴らの野営地へ行け。皆殺しにせよ。Barrensへ逃げて仲間を呼び集める者がひとりもいないようにしろ。\n\nこの襲撃隊気取りの頭目を見つけたら、その首を持ってこい。我らが先祖伝来の地を踏みにじろうとする者どもへの見せしめにするのだ。", "事は済んだか？", "そなたはcentaurの血にまみれている。この感覚を覚えておくのだ。我らの民の間では、他にない誉れだ。\n\n最後の一体が倒れた瞬間が聞こえた。奴らの雷のような蹄の音は、もう響かぬ。見事だ！\n\n今日は我らの村にとって大いなる勝利の日だ。そして、我らの子らが今こそ必要とする安心をもたらした。心から感謝するぞ、若き{class}よ。", 0xbecb73df, 0x6c87ad7a, 0xc8aa5ea0, 0x2f9c6665, 0x84d7106d, "....." },
  [99081] = { "凶報", "Longwalker Malah's ReportをBloodhoof VillageのBrave Wildrunnerに届けてください。", "Malahの背中の矢が飛んできたと思われる方角に、新しいcentaurの野営地らしきものが見える。人の動きが慌ただしく、小さな襲撃隊がMulgoreまで入り込んできたことをうかがわせる。\n\nLongwalkerは、まだ固く握りしめた手に報告書を持っている。Brave Wildrunnerは、Malahの運命と、その殺害者たちのことを知りたがるだろう。", nil, "これは実に深刻な知らせだ。すぐにBaineに知らせねばならん！", 0xbff8ff1d, 0x9fa22e01, 0xb797647f, nil, 0x0c2241b6, "...m." },
  [99082] = { "最高族長", "Thunder BluffのHigh Chieftain Cairne Bloodhoofに謁見を求めてください。", "同胞を守ったそなたの勇気は称えられるべきだ。北西のThunder Bluff、暑い季節には我らに日陰を与えてくれる我らの偉大な都へ旅し、我が父に謁見を願い出るがよい。\n\n若きWarchief Thrallと共にこの平原を取り戻す突撃を率い、centaurを永遠に追い払ったのは父なのだ。High Chieftainとして、父は自らの勇気が称えられるよう力を尽くしたそなたに、惜しみなく報いるであろう。\n\nHigh Chieftainのもとへ行くにはリフトに乗らねばならぬ。父は中央の台地におられる。", nil, nil, 0xccabdf4c, 0xf6ae33c9, 0x42612576, nil, nil, "...mm" },
  [99101] = { "我らが古き敵", "Longwalker Malah's ReportをBaine Bloodhoofに届けてください。", "Baine Bloodhoofが我らの村を率いている。彼にこの侵入のことをすぐに知らせねばならん。\n\nLongwalker Malahの報告書を彼のもとへ持っていけ。町の中心にいるはずだ。\n\nさあ、急げ。一刻の猶予もないぞ！", "何を持ってきた、{class}？", "<Baineは報告書を読み、その眼差しが険しくなる。>\n\nこのままにはしておかぬ。届けてくれて感謝する、{name}。", 0x5ea85fb3, 0xb468c9d1, 0x7a1841a0, 0x817d19e6, 0xd03a5cdc, "....." },
  [99108] = { "組み手の試合", "Tang Stonehoofのために、他のプレイヤーかNovice Warriorsを決闘で3回倒してください。", "ようこそ、若き{class}よ。そなたはウォリアーではないゆえ、我はその道を教えることはできぬが、だからといって我の指導から得るものがないわけではない。\n\n目の前にあるのが闘技場だ。その中では、誰を母と呼ぶかも、剣を振るうか弓を振るうかも関係ない。皆が平等であり、皆が直接の戦いの中で角を研ぐことを学ぶ。\n\n我らの場に入り、我らのやり方を自ら学ぶか？ ここにいる見習いの誰と戦ってもよいし、他の意欲ある相手でもよい。どちらでも我はかまわぬ。", nil, "その腕前で我に誉れを与えてくれたな、{class}。新たな世代にも、まだ望みはあるのかもしれぬ。\n\nこれを持っていき、傷の手当てをするがよい。この過酷な世界では、さらに多くの戦いがそなたを待っている。", 0x125afe74, 0xbc7d47d1, 0x96150aaf, nil, 0x087887f7, "...m." },
  [99123] = { "影の中で迷う", "Pal'juhがKolkar Cragから脱出するのを手助けし、成功の知らせをSen'jin VillageのMaster Vornalに届けてください。", "自分ひとりで岩山を少し偵察してみることにしたんです。運の悪いことに、よりによって魔力が尽きてしまって、それ以来ここに隠れて動けずにいるのです。\n\n逃げるのを手伝っていただけたら、ありがたいのですが。", nil, "ああ、Pal'juhのやつ、また面倒に巻き込まれたのか？\n\n今度こそ、一人で行くことについて教訓を学んでくれるといいんだがな。助けてくれてありがとう。あいつは有望なハンターなんだが、虎というよりraptorみたいに振る舞いがちでな。", 0xf927a39b, 0xafa4a299, 0x12a0451e, nil, 0x5c2dfedf, "...m." },
  [99127] = { "網の災難", "Crystal Lakeの漁の罠を確認する。", "今日は魚がちっとも食いつかないし、何かおかしなことになってる。針が空っぽってだけじゃないんだ。水の中に小魚一匹すら見かけないんだよ。\n\nここにいるLeeが、一晩かけて罠を仕掛けておいた。せめてそこに何か入ってないか確かめてきてくれ。何か変なものを見つけたら、必ず俺に見せてくれよ。", "話せるほどの釣果はあったか？", "罠が全部こうなってるのか？新しい厄介なご近所さんは、俺たちが思っていた以上に被害を出しているらしい。何か手を打たないと、こっちは破産しちまう。", 0xfd1c30f7, 0x0d9c902b, 0x2f2e27b0, 0xe18b71d3, 0x83f33ecd, "....." },
  [99128] = { "ぬめる脅威", "Crystal Lakeのmurlocを倒してください。", "こいつは湖の向こう側にいるmurlocどもの仕業に違いねえ。気色悪いちっこい奴らで、気性も荒けりゃ、牙もそれに負けねえくらい鋭いんだ。\n\nこのまま放っておいたら、この湖のどこにも魚なんて一匹もいなくなっちまう。少しでも片づけてくれたら、すげえ助かるんだがな。", "奴らは死んだか？", "ここからでも奴らのさえずりが聞こえる。悪夢に出てきそうだ。まあ、これで足止めにはなるだろう。もっとも、すぐに数を取り戻すのは間違いないがな。", 0x57b02f48, 0x56d64bc2, 0xf5572a28, 0x41433bf0, 0x59a544bd, "....." },
  [99129] = { "Murlocのことで来た男", "Jasonのmurloc問題について、Remy \"Two Times\"と話してください。", "Remyがこないだmurlocのことを言ってたな……あいつもきっと、俺と同じくらいあのちびどもが大嫌いなんだ。\n\nこれから先、murlocを俺の魚に近づけねえ方法について、何か考えがあるかもしれねえ。あいつのところへ行って話して、何か思いつくことがないか聞いてきてくれねえか。", nil, "murlocsのことは衛兵に警告し続けてきたんだが、聞く耳を持たないんだ。\n\nあいつらに仕返しする方法について、いくつか考えがある。ただ、そのために必要なものを集めるのに君の手を借りたい。", 0x03c7d9b1, 0x21971283, 0x01031b90, nil, 0x80005308, "...m." },
  [99130] = { "魅力的な申し出", "murlocをおびき寄せる餌の材料を集めてください。", "murlocをどうにかする方法なら、いくつか考えがある。そのうちのひとつは、ついでに他の連中の助けにもなるんだ。\n\nこのあたりの農場によく生えてるduskweedって雑草があってな、大量に摂ると、その花びらはたいていの動物に毒なんだ。その草でmurlocの餌を作れば、あいつらが近寄らないように仕込めるかもしれない。\n\nおまけに農家の畑もきれいになる。まさに一石二鳥……まさに一石二鳥だよ。", "全部見つかったか？", "ちょっと待ってくれ……\n\nごく簡単な餌だが、誰かのペットが食いつかない限り安全なはずだ。Jasonには絶対に食べるなと言っておいてくれ。", 0x77b84f75, 0xac7d3753, 0x5ab48582, 0xd1593a3f, 0x82fd44b6, "....." },
  [99131] = { "成功への餌", "Jason Mathersのところへ戻ってください。", "今日の後で餌を取りに来ていいって、Mathersに伝えてくれ。正しい使い方をざっと説明してやるよ。\n\nこれであいつもまたすぐに魚を売れるようになるといいな。そうすりゃ、この世のmurlocも減るってもんだ。", nil, "毒餌？魚が食べないのなら、それでうまくいくはずだ。後でRemyのところに取りに行くよ。", 0x1bee81f6, 0x8a176a1a, 0x32a450c9, nil, 0x34da7bf2, "...m." },
  [99134] = { "規律", "Executor ZygandのためにDeathguardを$N1人懲らしめてください。", "お前はDeathguardの一員ではない。ゆえに、まだ私を失望させていない。\n\n比較的無能ではないことへの褒美として、その才能を過剰なまでに示した者どもを罰する役目を与えよう。\n\nさっさと行け……{name}、だったか？……さもなくば、お前の名を私の帳簿に書き加えて、他の誰かへの褒美にしてやる。", nil, "死の中で我らに許された喜びは、ごくわずかだ。幸いなことに、痛みはその筆頭だ。\n\n今日、お前は私を喜ばせた。ゆえにDark Ladyも喜ばせたということだ。もっと役に立ってもらえるかもしれんな。", 0xdd51fa9d, 0xac918806, 0x6d1e5127, nil, 0x6bbbc36b, "...m." },
  [99141] = { "忍耐", "Executor Zygandのために、Deathguard Dillinger、Deathguard Kristof、Gordoから報告を受け取ってください。", "勘違いするなよ、{class}。Dark Ladyはその意志が完璧に遂行されることを求めておられる。Executorとして、それを果たさせるのが私の務めだ。\n\n私の配下のDeathguardたちの何人かから、報告が届いていない。言うまでもなく、我慢の限界だ。奴らの報告書を手に入れ、Dark Ladyの名のもとに私のところへ持ってこい。\n\nDeathguard Dillingerはここから西の墓地のそばにいる。Deathguard Kristofは東の中継所に配置されている。それと、abominationのGordoの様子も見てこい。あいつはStillwater Pondの近くを西へさまよっている。", "その報告書を手にしているんだろうな、でなければ目の前から失せろ。", "abominationに役立つものが書けるなどと考えた私が愚かだった。この判断の誤りは、我々だけの秘密にしておこう。\n\nお前は私を喜ばせた。ゆえにDark Ladyも喜ばせたということだ。お前にはまだ望みがあるかもしれんな。", 0x03e649d8, 0xa63a441f, 0xf9c1160a, 0xe2b93bff, 0x42825a52, "....." },
  [99142] = { "Tomb Weed", "Tomb Weedを$N1個集め、Junior Apothecary Hollandのところへ届けてください。", "東のBalnir Farmsteadの方へ向かうなら、他にもやってもらいたいことがある。近頃は良い助手を見つけるのが実に難しい。Gordoとのお前の一件が、それを実にはっきりと示しているようにな。\n\n私はdoom weedを手に入れるたびに、ちょっとした錬金術的な改良を施し、あの農場に植え直して、我が究極の創造物を育てている。私はそれをtomb weedと呼んでいる。それこそが、我が輝かしい運命の先触れとなるのだ。\n\n向こうにいる間は、そのあたりのScourgeから目を離すな。奴らはどうも……引き寄せられるようなのだ……その草に。興味深い。", "また邪魔が入ったか！いや待て、お前か。墓草は取り戻せたか？", "実に輝かしい！\n\n<Junior Apothecary Hollandは雑草を調べる。>\n\nふむ、もう少し凶暴に育っていてほしかったのだが。とはいえ、進歩は進歩だ！\n\n今日のお前の行いの結果、実に多くの者が死ぬだろう。誇りに思うがいい。", 0x739d084a, 0xa7eb6323, 0xdb1241f1, 0x6fa36b9d, 0xa4122385, "....." },
  [99143] = { "瓶と装身具", "近くのMurlocのキャンプから、きらきら光るガラクタを$N1個集めてください。", "あの魚人どもは本物の魚みたいな考え方をするに違いない、だろ？ つまり、あいつらが好きなものは何でも、魚も好きってわけだ！\n\nあいつらのガラクタを漁って、いい餌になりそうなものを何か持って帰ってきてくれたら、礼をするよ。", "何を見つけた？何か面白い物は？", "面白い品揃えだね。これなら十分使えそうだ！\n\nこれは私の昔の道具の一部だよ。釣りの足がかりをつかもうとしている人の助けになるはずだ。", 0x1ffcd534, 0xa43c8de8, 0xbad1ccc4, 0xe8e7e686, 0x00e2e45c, "....." },
  [99144] = { "避難先を求めて", "Bareth DawnstoneがCrusader's Outpostから脱出するのを手助けし、彼の無事をBrillのShari Stilwellに報告してください。", "見つけてくださって、光の祝福を。Bandarion KeepからBrillのShari Stilwellへ伝言を届けに行く途中で、この化け物どもに捕まってしまったのです。奴らは心に憎しみを抱いて光を振るう。そのせいで、私に残ったわずかな血さえも煮えたぎるのです。私が瞑想して求めるすべて……守ろうと努めるすべてに反することです！\n\n<Bareth Dawnstoneは気を落ち着ける。>\n\n私のような者をいまだに快く思わない者がいるのは知っていますが、私たちの意図は純粋だと断言します。ここから逃げるのを手伝ってくだされば、永遠に感謝いたします。", nil, "Dawnstoneを助けてくれたあなたに祝福を。我らの教団はまだここに根を下ろしている最中で、{name}にとって、これほど有望な者を時が来る前に失うのは痛ましいことでしょう。\n\nどうか、感謝の印としてこれを受け取ってください。もし我らの道に関心を持つことがあれば、我らの修道院Bandarion KeepはSolliden Farmsteadの北西の崖の上にあります。光に導きを求める者は誰でも歓迎します。", 0x6fee2f1e, 0xa52445cd, 0x66ee6a85, nil, 0x89de788b, "...m." },
  [99145] = { "A Winter Veil Gift", nil, nil, nil, nil, 0x919f9efa, nil, nil, nil, nil, ".mmmm" },
  [99152] = { "上のごとく、下もまた", "Hilda the BreakerのためにFaintly Glowing Boneを$N1個集めてください。", "南西のShadowvaleにいるTarnishedは確かに問題だが、町の地下の貯蔵庫が膿んで、Bandarion Keepに対する本格的なScourgeの反乱になるのを許すわけにはいかない。\n\n万一そうなった時に備えて、この訓練生たちを一人前にしておく必要がある。だがお前には、私が言うところの速成訓練を受けてもらう。\n\nShadowvaleの地下へ行き、さらに調べるため、奴らの忌まわしい骨をいくつか回収してこい。最初の蘇生の魔力をまだ残しているものが必要だ。つまり、光っているものだ。", "手ぶらで戻ってきたんじゃないだろうな。私に要るのは、頼んだ骨か、それを入手しようと少なくとも全力を尽くした証として、担架に乗ったお前の体か、どちらかだ。", "よくやった、新兵。お前もまだものになるかもしれんな。\n\nこの骨があれば、これほどの脅威がなぜこんなにも長く気づかれずにいられたのか、もっとよく理解できるかもしれん。", 0x8eef2a2e, 0xbff792d1, 0x1d6e04db, 0xe3908d93, 0xae3a943c, "....." },
  [99153] = { "逃した大物", "Ephram Barbaroのために、Shadowvaleの地下でHidden Crystal Fragmentを見つけてください。", "おい、お前！ 我々の仲間内じゃ噂が広まるのは早いんだ。Naxxramasとの戦いの残骸のあたりで、お前が教団員どもを相手にやった仕事のことは聞いたぞ。\n\n問題は、その教団員のひとりが集束水晶のかけらを持って逃げたことだ。まだ力が残っているらしい。俺たちの一番の見立てじゃ、Shadowvaleの地下のどこかにある。そいつが奴らを蘇らせているか、強くしているかのどっちかで、どっちもごめんだろう。\n\n手に負えなくなる前に、その水晶を見つけ出せ。", "あのいまいましい物は見つかったか？", "よくやった、しかも早い！さて、ここからが私のお気に入りの部分だ……", 0x173355cb, 0x78ca93b4, 0x5b0503ae, 0x158597e1, 0xd800d00b, "....." },
  [99156] = { "後衛の巡回", "Riptear's HeartをDeathguard Linneaに届けてください。", "くそっ！ お前が巡回に出ている間に、新しい報告が入った。Venomweb Valeの近く、Eastern Tirisfal Gladesで、rogue abominationがうろついているのが目撃された。\n\n何かがおかしい。abominationが誰にも気づかれずにBulwarkをすり抜けるはずがない。\n\nこの件は、厳密に知る必要のある者だけにとどめておけ。とはいえ、そんな化け物は簡単には倒れん。奴の次の食事で終わりたくなければ、仲間が必要だ。\n\nこれをやり遂げれば、しかるべき報酬を与える。事を成した証として、奴の心臓を持ってこい。", "例のちょっとした問題は片づいたか？", "お前は、すべてのForsakenが持つ狡猾さと連携の証だ。思考なきScourgeには決して持ち得ぬものだ。\n\n約束どおり、骨折りの礼としてこれを受け取ってくれ。", 0x889b08c3, 0x64da93a0, 0x08dcb58d, 0x45c20a1e, 0xc963fae0, "....." },
  [99158] = { "山の夜明け", "ろうそくの箱をMisty Pine RefugeのFather Gavinに届ける。", "山の中に、Argent Dawnという組織に属しているプリーストがいる。邪悪なものや不自然なものを見つけ出して滅ぼすことに身を捧げた、聖なる集団だ。\n\nだがFather Gavinは、武器を手に取るよりも、誰でも助けて癒やそうとするタイプでな。古い建物を修理して旅人の休憩所にして、Misty Pine Refugeと名付けたんだ。届けなきゃならない聖なるろうそくの荷があるんだが、そっちへ行くなら持っていってもらえないか？", "今日は、なぜ光があなたをここへ導いたのでしょう？", "ああ、Ironforgeのろうそくですね。\n\nこの庵ではほとんど自分の力で暮らせていますが、街や信心深い人々からいただけるとありがたいものが、いくつかあるのです。", 0x36d4d42c, 0xa2cefc05, 0x3e817a20, 0x1e73f441, 0xba70784a, "....." },
  [99159] = { "ぬくもりを求めて", "薪を$N1本集めてください。", "わしの炉辺は、どんな魂でも温めるために開かれておる。だが、できればひとつ手を貸してもらいたい。\n\n薪がもっと要るだけなのだ。普段なら自分でやるのだが、他の用事にかかりきりでな。", "光があなたの務めを導きますように。", "ああ、完璧だ。これで足りる。今すぐ使うには湿りすぎているものは、乾かしておこう。\n\nさて、もしよければ、手伝ってほしい仕事がまだあるんだ。", 0xd2e96c81, 0xe7dfe34d, 0x440461b1, 0x02ed172f, 0x50273776, "....." },
  [99160] = { "Rimeの怒り", "minor ice elementalを$N1体倒してください。", "近くのエレメンタルに気づいたかもしれんな。数日前、山頂から岩と氷の棚が崩れ落ちて、奴らを怒らせてしまったのだ。\n\nこの凍てつく山々は、精霊が形をとらずとも、並のドワーフや人間にとってはすでに危険な場所だ。わしはもう戦いに向いた身ではない……だから、精霊を少しでも倒してくれれば、道がより安全になる。", nil, "ただ彼らをなだめられたらよかったのですが。残念ながらそれは私の知識の及ばないことでしたし、野放しにしておくには危険すぎました。", 0x53be69cf, 0xaa060f30, 0x59b45096, nil, 0x95b19818, "...m." },
  [99161] = { "Rimeの怒り", "Avalaを倒し、そのコアを取り戻してください。", "落石の後に最初に現れたエレメンタルは、ほかのものより大きかった。それに、私の見たところ、そいつが時々起こる天候の変化や、ほかの小さな崩落の原因になっているようだ。\n\n私はそいつを「Avala」と呼んでいる。そいつを倒して、証拠としてコアを持ってきてくれたら、褒美をやろう。", "冬に用心しろよ、友よ。", "光の祝福がありますように、{class}。あなたの尽力で、この地域はずっと安全になりました。無用な死を防ぐ助けにもなるでしょう。", 0x53be69cf, 0xd6788d7a, 0x425a6958, 0x69cffb7c, 0x7feb3446, "....." },
  [99162] = { "危険な寒さ", "倒れた山岳兵たちのライフルを集めてください。", "Ironforgeの山岳兵でさえ、Dun Moroghの峰々を越える時には気を抜けん。落ちてくる雪や氷のせいで、経験の浅い者が命を落とすことも多いのだ。\n\n崩落の後は、たいてい生存者や犠牲者の痕跡を探すようにしておる……何も見つからんよう、光に祈りながらな。だが精霊が暴れておるから、あまり遠くへは出歩かんようにしてきた。行方知れずの山岳兵を探して、そのライフルを持ってきてくれれば、わしがIronforgeへ返しておこう。", "何の用だ？", "山岳兵たちは自分の名をライフルの銃床に刻むんだ。何かあったときの身元確認に役立つ。これはIronforgeへ送り返そう。向こうで誰かが家族に渡してくれるだろう。", 0x1ea8928b, 0x99bbd6c8, 0x3a1c1812, 0xece653c6, 0x49b853c2, "....." },
  [99191] = { "羊毛の寄付", nil, nil, "High Orderは現在、羊毛の布の寄付を受け付けている。\n\n羊毛の布60枚を寄付すれば、その寛大な行いに対してHigh Orderから十分な評価を得られるだろう。羊毛60枚あれば、当面のHigh Orderの必要には十分なはずだ。\n\n羊毛の布を60枚持っていて寄付する準備ができているなら、今ここで受け取ろう。", nil, 0xaad71c6f, nil, nil, 0xec1c7e4f, nil, ".mm.m" },
  [99196] = { "羊毛の寄付", nil, nil, "Windshapersは現在、羊毛の布の寄付を受け付けている。\n\n羊毛の布60枚を寄付すれば、その寛大さに対してWindshapersから十分な評価を得られるだろう。\n\n羊毛の布を60枚持っていて寄付する準備ができているなら、今ここで受け取ろう。", nil, 0xaad71c6f, nil, nil, 0x23004f34, nil, ".mm.m" },
  [99197] = { "絹の寄付", nil, nil, nil, nil, 0xaa4c5243, nil, nil, nil, nil, ".mmmm" },
  [99260] = { "Fillionの任務", "ValanaarのElaadrin Evengaleと話す。", "私はOverlook Standing Stonesから、エレメンタルのエネルギーの流れに関する重要なデータを回収する任務を負っていました。そのデータは、SkywallとAzerothの間を安全に行き来するという我々の計画に欠かせません。計算を助けるそのデータがなければ、エレメンタル界を抜けてskycutter船を操ろうとする試みは失敗するでしょう。\n\nデータはもう失われたも同然で、私にはもう一度集めに行ける状態ではありません。Supreme Magisterにあなたが私を救ってくれたことを伝えたところ、もう一度あなたと話したいとのことです。", nil, "Fillionを救ってくれてありがとうございます、{name}。彼が取り戻すよう命じられたデータがどれほど重要か、きっと聞いたことでしょう。\n\nそのデータがなければ、Azerothへの安全な移動路を開く私たちの見通しは深刻な危機にさらされます。密偵によれば、Windshapersは自ら次元を渡る手段を手に入れ、きっとこの秘密を独占しようとしているはずです。\n\nいつものように、彼らは独善的な傲慢さを民の幸福よりも優先しています。Al'Akethと大差ありません。", 0x6d5d3e21, 0x73833554, 0x8b8e3ec7, nil, 0x6df73fd1, "...m." },
  [99267] = { "不幸な最期", nil, nil, nil, nil, 0xc0c4b3d4, nil, nil, nil, nil, ".mmmm" },
  [99411] = { "Kyleが行方不明！", "MulgoreのBloodhoof VillageにいるAhab Wheathoofは、自慢の子犬Kyle the Frenziedに餌をやってほしいと言っています。\n\nKyleにTender Strider Meatを食べさせ、Ahab Wheathoofのところへ戻って下さい。", "助けて、{name}！ 大事な子犬のKyleが逃げちゃったんだ！ きっとBloodhoof Villageのあたりで、迷子になってお腹をすかせて走り回ってるんだ。\n\nあの子を見つけて、ごはんをあげてくれないかな？ 食べたら落ち着いて、家に帰ってくるはずだから。\n\nごはんをあげるには、食べ物を探さないといけない。あの子の大好物は、やわらかいstriderの肉なんだ。東へ行けば、striderがたくさんいるはずだよ。一頭仕留めて、そのおいしい肉をKyleのところへ持っていって。町でKyleを見かけたら、肉を置いてあげて。きっと君のところへ来るから。", nil, nil, 0x8d0c2e05, 0x1d37ba26, 0xdd2f4f8d, nil, nil, "...mm" },
})
